# Analyze the demo pair to understand the transformation rule
# Input is 12x12, output is 4x4
# This suggests each output cell comes from a 3x3 block of the input

demo_input = [
    [2, 2, 2, 5, 2, 5, 1, 1, 5, 5, 1, 5],
    [2, 2, 2, 5, 5, 5, 5, 1, 1, 5, 1, 5],
    [2, 2, 2, 5, 2, 2, 5, 5, 1, 1, 5, 5],
    [5, 5, 5, 5, 1, 1, 4, 5, 4, 7, 7, 7],
    [2, 5, 2, 5, 5, 5, 4, 5, 4, 7, 7, 7],
    [5, 2, 2, 1, 1, 1, 5, 4, 4, 5, 7, 7],
    [5, 2, 2, 5, 7, 7, 5, 5, 5, 1, 1, 5],
    [2, 2, 2, 7, 7, 7, 0, 5, 5, 1, 5, 1],
    [5, 2, 5, 7, 7, 5, 0, 0, 5, 1, 5, 1],
    [7, 7, 5, 4, 4, 4, 1, 5, 1, 5, 4, 5],
    [5, 7, 5, 4, 5, 4, 1, 5, 1, 5, 5, 4],
    [5, 7, 7, 5, 5, 5, 1, 5, 1, 5, 5, 5]
]

demo_output = [
    [2, 2, 1, 1],
    [2, 1, 4, 7],
    [2, 7, 0, 1],
    [7, 4, 1, 4]
]

def get_block_value(block):
    """Get the non-5 color value from a 3x3 block"""
    non_5_colors = set()
    for r in range(3):
        for c in range(3):
            if block[r][c] != 5:
                non_5_colors.add(block[r][c])

    if len(non_5_colors) == 0:
        return 5
    elif len(non_5_colors) == 1:
        return non_5_colors.pop()
    else:
        # Multiple non-5 colors - pick the one that appears most frequently
        freq = {}
        for r in range(3):
            for c in range(3):
                color = block[r][c]
                if color != 5:
                    freq[color] = freq.get(color, 0) + 1
        return max(freq.keys(), key=lambda x: freq[x])

# Verify the rule
print("Verification:")
for i in range(4):
    for j in range(4):
        start_r, start_c = i * 3, j * 3
        block = [row[start_c:start_c+3] for row in demo_input[start_r:start_r+3]]
        predicted = get_block_value(block)
        actual = demo_output[i][j]
        status = "✓" if predicted == actual else "✗"
        print(f"Block [{i},{j}] (rows {start_r}-{start_r+2}, cols {start_c}-{start_c+2}): predicted={predicted}, actual={actual} {status}")

